   Check(errors.Count==0,"Actual HUD, inventory, dialogue and boss scenes render without runtime errors");File.WriteAllText(Out+(SessionState.GetBool("Naki.CombatIceV2.Preview",false)?"preview-result.txt":"smoke-result.txt"),"PASS "+checks+" checks: five-room ice map; new foes and differentiated cover; original save migration; 69 short recorded combat cues; crystal armor and phased beast; expedition journal; ice spells and audio; isolated checkpoint/backup; cross-island gear and origin; boat arrival; narrative skill discovery; no early wheel/child repair; origin-specific rest and old-save normalization; canal-only rain ending; tutorial enemies; second-island shield, skills, stronger phased bosses; repeated-load growth; five viewport aspect/size cases; fitted weapon text; native HD/QHD/4:3 captures.\n");End(0);
